   546    // TODO(wvo): add further options to have indentation/newlines.
   547    void ToString(bool strings_quoted, bool keys_quoted, std::string &s) const {
   548      if (type_ == FBT_STRING) {
   549        String str(Indirect(), byte_width_);
   550        if (strings_quoted) {
   551          flatbuffers::EscapeString(str.c_str(), str.length(), &s, true, false);
   552        } else {
   553          s.append(str.c_str(), str.length());
