   557        if (keys_quoted) {
   558          flatbuffers::EscapeString(str, strlen(str), &s, true, false);
   559        } else {
   560          s += str;
   561        }
   562      } else if (IsInt()) {
   563        s += flatbuffers::NumToString(AsInt64());
   564      } else if (IsUInt()) {
   565        s += flatbuffers::NumToString(AsUInt64());
   566      } else if (IsFloat()) {
   567        s += flatbuffers::NumToString(AsDouble());
   568      } else if (IsNull()) {
   569        s += "null";
   570      } else if (IsBool()) {
   571        s += AsBool() ? "true" : "false";
   572      } else if (IsMap()) {
