   585        AppendToString<Vector>(s, AsVector(), keys_quoted);
   586      } else if (IsTypedVector()) {
   587        AppendToString<TypedVector>(s, AsTypedVector(), keys_quoted);
   588      } else if (IsFixedTypedVector()) {
   589        AppendToString<FixedTypedVector>(s, AsFixedTypedVector(), keys_quoted);
